<x-app-layout><div class="space-y-5" x-data="returnForm()"><div><p class="text-sm text-black/45">Kasir</p><h2 class="mt-1 text-2xl font-semibold">Retur Penjualan</h2></div>@if($errors->any())<div class="rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700"><ul class="list-disc pl-5">@foreach($errors->all() as $error)<li>{{ $error }}</li>@endforeach</ul></div>@endif<form method="POST" action="{{ route('kasir.retur.store') }}" class="space-y-5">@csrf<div class="grid gap-4 rounded-2xl border bg-white p-5 md:grid-cols-3"><div><label>No. Retur</label><input name="return_number" value="{{ old('return_number','RET-'.now()->format('YmdHis')) }}" required class="mt-2 w-full rounded-xl border px-3 py-2"></div><div><label>Transaksi</label><select name="sale_id" x-model="saleId" @change="loadItems()" required class="mt-2 w-full rounded-xl border px-3 py-2"><option value="">Pilih invoice</option>@foreach($sales as $sale)<option value="{{ $sale->id }}">{{ $sale->invoice }}</option>@endforeach</select></div><div><label>Tanggal</label><input type="datetime-local" name="return_date" value="{{ now()->format('Y-m-d\TH:i') }}" required class="mt-2 w-full rounded-xl border px-3 py-2"></div></div><div class="rounded-2xl border bg-white p-5"><h3 class="font-semibold">Item Retur</h3><template x-for="(item,index) in items" :key="item.key"><div class="mt-3 grid gap-3 rounded-xl border p-3 md:grid-cols-[1fr_140px_40px]"><select :name="'items['+index+'][sale_item_id]'" x-model="item.sale_item_id" required class="rounded-lg border px-3 py-2"><option value="">Pilih item</option><template x-for="option in saleItems" :key="option.id"><option :value="option.id" x-text="option.label"></option></template></select><input type="number" min="1" :name="'items['+index+'][quantity]'" x-model.number="item.quantity" required class="rounded-lg border px-3 py-2"><button type="button" @click="removeItem(index)" x-show="items.length>1" class="text-red-500">×</button></div></template><button type="button" @click="addItem()" class="mt-4 rounded-xl border px-4 py-2">+ Tambah Item</button></div><div class="rounded-2xl border bg-white p-5"><textarea name="reason" rows="3" placeholder="Alasan retur" class="w-full rounded-xl border px-3 py-2"></textarea><button class="mt-4 rounded-xl bg-[#171719] px-5 py-3 font-semibold text-white">Simpan Retur</button></div></form></div><script>function returnForm(){const data=@json($sales->mapWithKeys(fn($s)=>[$s->id=>$s->items()->with('product')->get()->map(fn($i)=>['id'=>$i->id,'label'=>$i->product->name.' — qty '.$i->quantity])])->all());return{saleId:'',saleItems:[],items:[{key:Date.now(),sale_item_id:'',quantity:1}],loadItems(){this.saleItems=data[this.saleId]||[];this.items=[{key:Date.now(),sale_item_id:'',quantity:1}]},addItem(){this.items.push({key:Date.now()+this.items.length,sale_item_id:'',quantity:1})},removeItem(i){this.items.splice(i,1)}}}</script></x-app-layout>